1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// The single customer a scenario is quoted for.
15	pub struct Customer {
16	    pub years_with_mhpco: u32,
17	}
18	
19	pub struct Item {
20	    pub item_type: String,
21	    pub material: String,
22	    pub enchantment: u32,
23	    pub cursed: bool,
24	}
25	
26	const PROCESSING_FEE: u64 = 5;
27	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
28	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
29	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
30	
31	const SWORD_BASE_PREMIUM: u64 = 100;
32	const AMULET_BASE_PREMIUM: u64 = 60;
33	const STAFF_BASE_PREMIUM: u64 = 80;
34	const POTION_BASE_PREMIUM: u64 = 40;
35	const COMPONENT_BASE_PREMIUM: u64 = 25;
36	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
37	const COMPONENT_BLOCK_SIZE: usize = 3;
38	const CURSE_SURCHARGE_PERCENT: u64 = 50;
39	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
40	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
41	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
42	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
43	const LOYALTY_YEARS: u32 = 2;
44	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
45	
46	/// Components, such as runes and moonstones, are the parts the MHPCO insures
47	/// alongside main items and the only items the building-block offer covers.
48	fn is_component(item: &Item) -> bool {
49	    matches!(item.item_type.as_str(), "rune" | "moonstone")
50	}
51	
52	/// The MHPCO price list: the base premium the catalogue lists for one item.
53	fn base_premium(item: &Item) -> u64 {
54	    if is_component(item) {
55	        return COMPONENT_BASE_PREMIUM;
56	    }
57	    match item.item_type.as_str() {
58	        "amulet" => AMULET_BASE_PREMIUM,
59	        "staff" => STAFF_BASE_PREMIUM,
60	        "potion" => POTION_BASE_PREMIUM,
61	        _ => SWORD_BASE_PREMIUM,
62	    }
63	}
64	
65	/// The building-block offer is reserved for a group of exactly 3 alike
66	/// components; a larger group does not qualify, it is priced per component.
67	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
68	    alike_component_count == COMPONENT_BLOCK_SIZE
69	}
70	
71	/// The price the MHPCO charges for one group of alike components: the
72	/// building-block offer when the group qualifies, otherwise per component.
73	fn component_group_base_premium(count: usize) -> u64 {
74	    if qualifies_as_building_block(count) {
75	        COMPONENT_BLOCK_BASE_PREMIUM
76	    } else {
77	        count as u64 * COMPONENT_BASE_PREMIUM
78	    }
79	}
80	
81	/// Two components are "alike" when they share this key. For the MHPCO,
82	/// alike means the very same catalogue type: a rune and a moonstone are
83	/// never alike, so mixed component types form no building block.
84	fn alike_group_key(item: &Item) -> &str {
85	    &item.item_type
86	}
87	
88	/// The policy base premium: the sum of all insured items' base premiums,
89	/// with alike components priced per group so a block can be recognised.
90	fn policy_base_premium(items: &[Item]) -> u64 {
91	    let mut main_items_total = 0;
92	    let mut alike_component_counts: BTreeMap<&str, usize> = BTreeMap::new();
93	    for item in items {
94	        if is_component(item) {
95	            *alike_component_counts.entry(alike_group_key(item)).or_insert(0) += 1;
96	        } else {
97	            main_items_total += base_premium(item);
98	        }
99	    }
100	
101	    main_items_total
102	        + alike_component_counts
103	            .values()
104	            .map(|count| component_group_base_premium(*count))
105	            .sum::<u64>()
106	}
107	
108	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
109	#[derive(Clone, Copy)]
110	enum Debtor {
111	    Customer,
112	    Mhpco,
113	}
114	
115	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
116	/// settles the direction by itself once it is known who owes whom: an amount
117	/// the customer owes is rounded up, an amount the office owes is rounded down.
118	/// Intermediate amounts stay fractional; only the final amount is rounded.
119	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
120	    match owed_by {
121	        Debtor::Customer => amount.ceil() as u64,
122	        Debtor::Mhpco => amount.floor() as u64,
123	    }
124	}
125	
126	/// A policy-wide modifier is measured against the policy base premium, the
127	/// sum of all item base premiums, never against a single item.
128	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
129	    policy_base_premium * percent as f64 / 100.0
130	}
131	
132	/// Every item in a quote is treated as a first insurance, so the initial
133	/// assessment surcharge is charged on the whole policy base premium.
134	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
135	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
136	}
137	
138	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
139	/// highly enchanted. This is the premium-side threshold; the claim-side
140	/// reimbursement clause judges enchantment by its own, stricter threshold.
141	fn is_highly_enchanted(item: &Item) -> bool {
142	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
143	}
144	
145	/// An item-specific risk surcharge is charged on the base premium of the
146	/// affected item, never on the policy total.
147	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
148	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
149	}
150	
151	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
152	/// item that brings two of them is surcharged for each.
153	fn item_risk_surcharge(item: &Item) -> f64 {
154	    let mut surcharge = 0.0;
155	    if item.cursed {
156	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
157	    }
158	    if is_highly_enchanted(item) {
159	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
160	    }
161	    surcharge
162	}
163	
164	/// Item-specific modifiers apply to the base premium of the affected item,
165	/// never to the policy total, so the policy owes the sum of the items' own
166	/// risk surcharges.
167	fn item_risk_surcharges(items: &[Item]) -> f64 {
168	    items.iter().map(item_risk_surcharge).sum()
169	}
170	
171	/// A long-standing customer, with at least two years of business with the
172	/// MHPCO, has earned the loyalty discount.
173	fn is_long_standing(customer: &Customer) -> bool {
174	    customer.years_with_mhpco >= LOYALTY_YEARS
175	}
176	
177	/// The loyalty discount is a policy-wide modifier, so it is measured against
178	/// the policy base premium.
179	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
180	    if is_long_standing(customer) {
181	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
182	    } else {
183	        0.0
184	    }
185	}
186	
187	/// A contract is a follow-up when the customer already holds at least one
188	/// other contract with the MHPCO; the customer's very first is not.
189	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
190	    contracts_already_held > 0
191	}
192	
193	/// Every contract after the customer's first earns the follow-up discount. It
194	/// is a policy-wide modifier, so it is measured against the policy base premium.
195	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
196	    if is_follow_up_contract(contracts_already_held) {
197	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
198	    } else {
199	        0.0
200	    }
201	}
202	
203	/// What the customer's standing with the MHPCO adds to or takes off the policy
204	/// base premium: the net of every policy-wide surcharge and discount. Positive
205	/// amounts raise the premium, negative amounts lower it.
206	fn policy_wide_modifiers(
207	    customer: &Customer,
208	    contracts_already_held: u32,
209	    policy_base_premium: f64,
210	) -> f64 {
211	    first_insurance_surcharge(policy_base_premium)
212	        - loyalty_discount(customer, policy_base_premium)
213	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
214	}
215	
216	/// The premium the policy earns before the processing fee: the policy base
217	/// premium, plus what the items' own risks cost, plus what the customer's
218	/// standing adjusts.
219	fn modified_policy_premium(
220	    customer: &Customer,
221	    contracts_already_held: u32,
222	    items: &[Item],
223	) -> f64 {
224	    let policy_base_premium = policy_base_premium(items) as f64;
225	    policy_base_premium
226	        + item_risk_surcharges(items)
227	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
228	}
229	
230	/// The MHPCO adds its processing fee to every premium at the very end, after
231	/// every surcharge and discount has been settled.
232	pub fn quote_premium(
233	    customer: &Customer,
234	    contracts_already_held: u32,
235	    items: &[Item],
236	) -> u64 {
237	    rounded_in_mhpco_favor(
238	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
239	        Debtor::Customer,
240	    )
241	}
242	
243	/// Damage to a very highly enchanted item is reimbursed at only half the
244	/// damage amount. This claim-side threshold is deliberately stricter than, and
245	/// separate from, the premium-side high-enchantment risk surcharge: an item can
246	/// be enchanted enough to cost more to insure yet not enough to be halved.
247	fn is_reimbursed_by_half(item: &Item) -> bool {
248	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
249	}
250	
251	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
252	/// before the deductible is taken off. Full reimbursement is the MHPCO's
253	/// standing position: it is both what an item with no clause receives and what
254	/// the dragon-material clause prescribes, so that clause asks for no share of
255	/// its own. Only the halving clause departs from full reimbursement, and it
256	/// wins wherever it applies.
257	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
258	    if is_reimbursed_by_half(damaged_item) {
259	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
260	    } else {
261	        damage.amount as f64
262	    }
263	}
264	
265	/// The deductible applies per damage event, after the reimbursement clauses.
266	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
267	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
268	}
269	
270	/// What the MHPCO owes for an incident filed against a policy: the sum of the
271	/// reimbursements its damages earn, rounded in the office's favor at the end.
272	pub fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
273	    let total: f64 = incident
274	        .damages
275	        .iter()
276	        .map(|damage| {
277	            let damaged_item = items
278	                .iter()
279	                .find(|item| item.item_type == damage.item_type)
280	                .expect("the damaged item is insured by this policy");
281	            reimbursement_for(damaged_item, damage)
282	        })
283	        .sum();
284	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
285	}
